```dart
class CheckoutButton extends StatelessWidget {
  const CheckoutButton({
    super.key,
    required this.isSubmitting,
    required this.submit,
  });

  final bool isSubmitting;
  final VoidCallback submit;

  @override
  Widget build(BuildContext context) {
    final onActivate = isSubmitting ? null : submit;

    return Semantics(
      button: true,
      enabled: !isSubmitting,
      label: isSubmitting ? 'Submitting order' : 'Place order',
      // A null callback removes the accessibility action while disabled.
      onTap: onActivate,
      excludeSemantics: true,
      child: CustomCheckoutButton(
        onPressed: onActivate, // Also disables pointer and keyboard activation.
        isLoading: isSubmitting,
      ),
    );
  }
}
```

The key is using the same nullable callback for semantics, pointer, and keyboard activation. `enabled: false` describes state, but does not itself remove `onTap`.

```dart
testWidgets('checkout button exposes and activates enabled action', (tester) async {
  var submissions = 0;

  await tester.pumpWidget(
    MaterialApp(
      home: CheckoutButton(
        isSubmitting: false,
        submit: () => submissions++,
      ),
    ),
  );

  expect(
    tester.getSemantics(find.byType(CheckoutButton)),
    matchesSemantics(
      isButton: true,
      isEnabled: true,
      label: 'Place order',
      hasTapAction: true,
    ),
  );

  await tester.tap(find.byType(CustomCheckoutButton));
  expect(submissions, 1);
});

testWidgets('checkout button is labelled but cannot activate while submitting',
    (tester) async {
  var submissions = 0;

  await tester.pumpWidget(
    MaterialApp(
      home: CheckoutButton(
        isSubmitting: true,
        submit: () => submissions++,
      ),
    ),
  );

  expect(
    tester.getSemantics(find.byType(CheckoutButton)),
    matchesSemantics(
      isButton: true,
      isEnabled: false,
      label: 'Submitting order',
      hasTapAction: false,
    ),
  );

  await tester.tap(find.byType(CustomCheckoutButton));
  expect(submissions, 0);
});
```

Ensure `CustomCheckoutButton` treats `onPressed: null` as disabled for both its gesture handler and keyboard shortcuts.
